import { ValueObject } from '../../../shared/domain/value-object.js'
import { ValidationError } from '../../../shared/types/errors.js'

export const PRIORITY_LEVELS = ['low', 'medium', 'high', 'critical'] as const

export type PriorityLevel = (typeof PRIORITY_LEVELS)[number]

const NUMERIC_VALUE: Record<PriorityLevel, number> = {
  low: 1,
  medium: 2,
  high: 3,
  critical: 4
}

export class Priority extends ValueObject<{ value: PriorityLevel }> {
  private constructor(value: PriorityLevel) {
    super({ value })
  }

  static low(): Priority {
    return new Priority('low')
  }

  static medium(): Priority {
    return new Priority('medium')
  }

  static high(): Priority {
    return new Priority('high')
  }

  static critical(): Priority {
    return new Priority('critical')
  }

  static fromString(value: string): Priority {
    if (!(PRIORITY_LEVELS as readonly string[]).includes(value)) {
      throw new ValidationError(
        `Invalid priority '${value}'`,
        [`expected one of: ${PRIORITY_LEVELS.join(', ')}`]
      )
    }
    return new Priority(value as PriorityLevel)
  }

  get value(): PriorityLevel {
    return this.props.value
  }

  getNumericValue(): number {
    return NUMERIC_VALUE[this.value]
  }
}

