import { AggregateRoot } from '../../../shared/domain/aggregate-root.js'
import type { DomainEvent } from '../../../shared/domain/domain-event.js'
import {
  InvalidTaskStateTransitionError,
  ValidationError
} from '../../../shared/types/errors.js'
import type { IClock } from '../../../shared/types/interfaces.js'
import { SystemClock } from '../../../shared/types/interfaces.js'
import { TaskAssignedEvent } from '../events/task-assigned.event.js'
import { TaskCompletedEvent } from '../events/task-completed.event.js'
import type { Priority } from '../value-objects/priority.vo.js'
import { TaskId } from '../value-objects/task-id.vo.js'
import { TaskStatus } from '../value-objects/task-status.vo.js'
import type { TaskResult } from '../value-objects/task-result.vo.js'

export interface TaskProps {
  readonly id: TaskId
  readonly description: string
  readonly priority: Priority
  readonly status: TaskStatus
  readonly assignedAgentId: string | undefined
  readonly createdAt: Date
  readonly updatedAt: Date
}

/**
 * Task aggregate. Fully immutable: every state transition returns a NEW
 * Task carrying the accumulated uncommitted domain events and version + 1.
 * The original instance is never modified.
 */
export class Task extends AggregateRoot<TaskId> {
  private readonly props: Readonly<TaskProps>

  private constructor(
    props: TaskProps,
    domainEvents: readonly DomainEvent[],
    version: number
  ) {
    super(props.id, domainEvents, version)
    this.props = Object.freeze({ ...props })
  }

  static create(
    description: string,
    priority: Priority,
    clock: IClock = new SystemClock()
  ): Task {
    if (description.trim().length === 0) {
      throw new ValidationError('Task description cannot be empty')
    }
    const now = clock.now()
    return new Task(
      {
        id: TaskId.create(),
        description,
        priority,
        status: TaskStatus.pending(),
        assignedAgentId: undefined,
        createdAt: now,
        updatedAt: now
      },
      [],
      0
    )
  }

  /** Rebuild from persistence: no uncommitted events. */
  static reconstitute(props: TaskProps, version: number): Task {
    return new Task(props, [], version)
  }

  assignTo(agentId: string, clock: IClock = new SystemClock()): Task {
    if (agentId.trim().length === 0) {
      throw new ValidationError('Agent id cannot be empty')
    }
    const next = TaskStatus.assigned()
    if (!this.props.status.canTransitionTo(next)) {
      throw new InvalidTaskStateTransitionError(
        this.props.status.value,
        'assign'
      )
    }
    return this.transition(
      {
        ...this.props,
        status: next,
        assignedAgentId: agentId,
        updatedAt: clock.now()
      },
      new TaskAssignedEvent(this.id.value, agentId, this.props.priority, clock)
    )
  }

  complete(result: TaskResult, clock: IClock = new SystemClock()): Task {
    const next = result.isSuccess ? TaskStatus.completed() : TaskStatus.failed()
    if (
      this.props.assignedAgentId === undefined ||
      !this.props.status.canTransitionTo(next)
    ) {
      throw new InvalidTaskStateTransitionError(
        this.props.status.value,
        'complete'
      )
    }
    const now = clock.now()
    const durationMs = now.getTime() - this.props.createdAt.getTime()
    return this.transition(
      { ...this.props, status: next, updatedAt: now },
      new TaskCompletedEvent(this.id.value, result, durationMs, clock)
    )
  }

  /** Returns a copy with no uncommitted events (after publishing). */
  clearDomainEvents(): Task {
    return new Task(this.props, [], this.version)
  }

  private transition(props: TaskProps, event: DomainEvent): Task {
    return new Task(props, [...this.domainEvents, event], this.version + 1)
  }

  get description(): string {
    return this.props.description
  }

  get priority(): Priority {
    return this.props.priority
  }

  get status(): TaskStatus {
    return this.props.status
  }

  get assignedAgentId(): string | undefined {
    return this.props.assignedAgentId
  }

  get createdAt(): Date {
    return this.props.createdAt
  }

  get updatedAt(): Date {
    return this.props.updatedAt
  }
}

