import { describe, expect, it } from 'vitest'

import { AggregateRoot } from '../../../src/core/shared/domain/aggregate-root.js'
import { DomainEvent } from '../../../src/core/shared/domain/domain-event.js'
import { Entity } from '../../../src/core/shared/domain/entity.js'
import { ValueObject } from '../../../src/core/shared/domain/value-object.js'

class FakeId extends ValueObject<{ value: string }> {
  constructor(value: string) {
    super({ value })
  }
}

class ThingHappened extends DomainEvent {
  constructor(aggregateId: string) {
    super('thing.happened', aggregateId)
  }
}

class Widget extends Entity<FakeId> {
  constructor(id: FakeId, events: readonly DomainEvent[] = []) {
    super(id, events)
  }
}

class Gadget extends Entity<FakeId> {
  constructor(id: FakeId) {
    super(id)
  }
}

class Machine extends AggregateRoot<FakeId> {
  constructor(id: FakeId, events: readonly DomainEvent[], version: number) {
    super(id, events, version)
  }
}

describe('Entity', () => {
  it('compares by id, not reference', () => {
    expect(new Widget(new FakeId('a')).equals(new Widget(new FakeId('a')))).toBe(
      true
    )
    expect(new Widget(new FakeId('a')).equals(new Widget(new FakeId('b')))).toBe(
      false
    )
  })

  it('is not equal across different entity classes with the same id', () => {
    const widget = new Widget(new FakeId('a'))
    const gadget = new Gadget(new FakeId('a'))
    expect(widget.equals(gadget as unknown as Widget)).toBe(false)
  })

  it('is not equal to undefined', () => {
    expect(new Widget(new FakeId('a')).equals(undefined)).toBe(false)
  })

  it('exposes a frozen domainEvents array', () => {
    const widget = new Widget(new FakeId('a'), [new ThingHappened('a')])
    expect(Object.isFrozen(widget.domainEvents)).toBe(true)
    expect(widget.domainEvents).toHaveLength(1)
  })

  it('defensively copies the events passed to the constructor', () => {
    const events: DomainEvent[] = [new ThingHappened('a')]
    const widget = new Widget(new FakeId('a'), events)
    events.push(new ThingHappened('a'))
    expect(widget.domainEvents).toHaveLength(1)
  })
})

describe('AggregateRoot', () => {
  it('carries a version', () => {
    const machine = new Machine(new FakeId('m'), [], 3)
    expect(machine.version).toBe(3)
  })
})

describe('DomainEvent', () => {
  it('assigns eventId, name, aggregateId and occurredAt', () => {
    const event = new ThingHappened('agg-1')
    expect(event.eventId).toMatch(/^[0-9a-f-]{36}$/)
    expect(event.eventName).toBe('thing.happened')
    expect(event.aggregateId).toBe('agg-1')
    expect(event.occurredAt).toBeInstanceOf(Date)
  })
})

