import { describe, expect, it } from 'vitest'

import { DomainEvent } from '../../../src/core/shared/domain/domain-event.js'
import { InMemoryEventBus } from '../../../src/core/shared/infrastructure/event-bus.js'
import type { ILogger } from '../../../src/core/shared/infrastructure/logger.js'

class TestEvent extends DomainEvent {
  constructor() {
    super('test.event', 'agg-1')
  }
}

class SpyLogger implements ILogger {
  readonly errors: string[] = []
  debug(): void {}
  info(): void {}
  warn(): void {}
  error(message: string): void {
    this.errors.push(message)
  }
}

describe('InMemoryEventBus', () => {
  it('delivers events to subscribed handlers', async () => {
    const bus = new InMemoryEventBus()
    const received: DomainEvent[] = []
    bus.subscribe('test.event', (e) => {
      received.push(e)
    })

    await bus.publish(new TestEvent())

    expect(received).toHaveLength(1)
    expect(received[0]?.eventName).toBe('test.event')
  })

  it('does nothing when there are no subscribers', async () => {
    const bus = new InMemoryEventBus()
    await expect(bus.publish(new TestEvent())).resolves.toBeUndefined()
  })

  it('isolates handler failures and logs them', async () => {
    const logger = new SpyLogger()
    const bus = new InMemoryEventBus(logger)
    const received: string[] = []
    bus.subscribe('test.event', () => {
      throw new Error('boom')
    })
    bus.subscribe('test.event', () => {
      received.push('second handler ran')
    })

    await bus.publish(new TestEvent())

    expect(received).toEqual(['second handler ran'])
    expect(logger.errors).toHaveLength(1)
  })

  it('stops delivering after unsubscribe', async () => {
    const bus = new InMemoryEventBus()
    let calls = 0
    const handler = (): void => {
      calls += 1
    }
    bus.subscribe('test.event', handler)
    bus.unsubscribe('test.event', handler)

    await bus.publish(new TestEvent())

    expect(calls).toBe(0)
  })

  it('supports async handlers', async () => {
    const bus = new InMemoryEventBus()
    let resolved = false
    bus.subscribe('test.event', async () => {
      await Promise.resolve()
      resolved = true
    })

    await bus.publish(new TestEvent())

    expect(resolved).toBe(true)
  })
})

