import { describe, expect, it } from 'vitest'

import {
  createToken,
  DependencyContainer,
  DependencyResolutionError
} from '../../../src/core/shared/infrastructure/dependency-container.js'

class Service {
  static instances = 0

  constructor() {
    Service.instances += 1
  }
}

describe('DependencyContainer', () => {
  it('resolves transient registrations to new instances', () => {
    Service.instances = 0
    const [REDACTED]'Service')
    const container = new DependencyContainer()
    container.register(token, () => new Service())

    const a = container.resolve(token)
    const b = container.resolve(token)

    expect(a).not.toBe(b)
    expect(Service.instances).toBe(2)
  })

  it('resolves singleton registrations to a shared instance', () => {
    Service.instances = 0
    const [REDACTED]'Service')
    const container = new DependencyContainer()
    container.registerSingleton(token, () => new Service())

    const a = container.resolve(token)
    const b = container.resolve(token)

    expect(a).toBe(b)
    expect(Service.instances).toBe(1)
  })

  it('registers pre-built values', () => {
    const [REDACTED]'config')
    const container = new DependencyContainer()
    container.registerValue(token, 'hello')

    expect(container.resolve(token)).toBe('hello')
  })

  it('supports factories that resolve their own dependencies', () => {
    const dep = createToken<string>('dep')
    const svc = createToken<string>('svc')
    const container = new DependencyContainer()
    container.registerValue(dep, 'world')
    container.register(svc, (c) => `hello ${c.resolve(dep)}`)

    expect(container.resolve(svc)).toBe('hello world')
  })

  it('throws a typed error for unknown tokens', () => {
    const container = new DependencyContainer()
    const [REDACTED]'missing')

    expect(() => container.resolve(token)).toThrow(DependencyResolutionError)
  })

  it('reports registration status via has()', () => {
    const [REDACTED]'x')
    const container = new DependencyContainer()

    expect(container.has(token)).toBe(false)
    container.registerValue(token, 'x')
    expect(container.has(token)).toBe(true)
  })
})

