import { describe, expect, it } from 'vitest'

import { TaskId } from '../../../src/core/domains/task-management/value-objects/task-id.vo.js'
import { ValidationError } from '../../../src/core/shared/types/errors.js'

describe('TaskId', () => {
  it('creates unique UUIDs', () => {
    const a = TaskId.create()
    const b = TaskId.create()
    expect(a.value).toMatch(/^[0-9a-f-]{36}$/)
    expect(a.equals(b)).toBe(false)
  })

  it('round-trips through fromString', () => {
    const original = TaskId.create()
    const restored = TaskId.fromString(original.value)
    expect(restored.equals(original)).toBe(true)
  })

  it('rejects non-UUID strings', () => {
    expect(() => TaskId.fromString('')).toThrow(ValidationError)
    expect(() => TaskId.fromString('not-a-uuid')).toThrow(ValidationError)
    expect(() => TaskId.fromString('12345')).toThrow(ValidationError)
  })
})

