import { describe, expect, it } from 'vitest'

import { TaskStatus } from '../../../src/core/domains/task-management/value-objects/task-status.vo.js'
import { ValidationError } from '../../../src/core/shared/types/errors.js'

describe('TaskStatus', () => {
  it('exposes factory statics with matching predicates', () => {
    expect(TaskStatus.pending().isPending()).toBe(true)
    expect(TaskStatus.assigned().isAssigned()).toBe(true)
    expect(TaskStatus.inProgress().isInProgress()).toBe(true)
    expect(TaskStatus.completed().isCompleted()).toBe(true)
    expect(TaskStatus.failed().isFailed()).toBe(true)
  })

  it('round-trips through fromString', () => {
    expect(TaskStatus.fromString('pending').equals(TaskStatus.pending())).toBe(
      true
    )
    expect(
      TaskStatus.fromString('in_progress').equals(TaskStatus.inProgress())
    ).toBe(true)
  })

  it('rejects unknown status strings', () => {
    expect(() => TaskStatus.fromString('done')).toThrow(ValidationError)
    expect(() => TaskStatus.fromString('')).toThrow(ValidationError)
  })

  it('allows only legal transitions', () => {
    expect(
      TaskStatus.pending().canTransitionTo(TaskStatus.assigned())
    ).toBe(true)
    expect(
      TaskStatus.pending().canTransitionTo(TaskStatus.completed())
    ).toBe(false)
    expect(
      TaskStatus.assigned().canTransitionTo(TaskStatus.completed())
    ).toBe(true)
    expect(
      TaskStatus.assigned().canTransitionTo(TaskStatus.failed())
    ).toBe(true)
    expect(
      TaskStatus.completed().canTransitionTo(TaskStatus.assigned())
    ).toBe(false)
  })

  it('marks completed and failed as terminal', () => {
    expect(TaskStatus.completed().isTerminal()).toBe(true)
    expect(TaskStatus.failed().isTerminal()).toBe(true)
    expect(TaskStatus.pending().isTerminal()).toBe(false)
  })
})

