import { describe, expect, it } from 'vitest'

import { Priority } from '../../../src/core/domains/task-management/value-objects/priority.vo.js'
import { ValidationError } from '../../../src/core/shared/types/errors.js'

describe('Priority', () => {
  it('orders numeric values low < medium < high < critical', () => {
    expect(Priority.low().getNumericValue()).toBe(1)
    expect(Priority.medium().getNumericValue()).toBe(2)
    expect(Priority.high().getNumericValue()).toBe(3)
    expect(Priority.critical().getNumericValue()).toBe(4)
  })

  it('round-trips through fromString', () => {
    expect(Priority.fromString('high').equals(Priority.high())).toBe(true)
  })

  it('rejects unknown priority strings', () => {
    expect(() => Priority.fromString('urgent')).toThrow(ValidationError)
    expect(() => Priority.fromString('')).toThrow(ValidationError)
  })

  it('compares by value', () => {
    expect(Priority.low().equals(Priority.low())).toBe(true)
    expect(Priority.low().equals(Priority.high())).toBe(false)
  })
})

