    const withOutput = TaskResult.success('done')
    expect(withOutput.isSuccess).toBe(true)
    expect(withOutput.output).toBe('done')
    expect(withOutput.errorMessage).toBeUndefined()

    const bare = TaskResult.success()
    expect(bare.isSuccess).toBe(true)
    expect(bare.output).toBeUndefined()
  })

  it('creates a failure result with an error message', () => {
    const failure = TaskResult.failure('it broke')
    expect(failure.isSuccess).toBe(false)
    expect(failure.errorMessage).toBe('it broke')
    expect(failure.output).toBeUndefined()
  })

  it('rejects failures with an empty message', () => {
    expect(() => TaskResult.failure('   ')).toThrow(ValidationError)
  })

  it('compares structurally', () => {
    expect(TaskResult.success('x').equals(TaskResult.success('x'))).toBe(true)
    expect(TaskResult.success('x').equals(TaskResult.failure('x'))).toBe(false)
  })
})

