} from '../../src/core/domains/task-management/repositories/sqlite-task.repository.js'
import { Priority } from '../../src/core/domains/task-management/value-objects/priority.vo.js'
import { TaskId } from '../../src/core/domains/task-management/value-objects/task-id.vo.js'
import { TaskStatus } from '../../src/core/domains/task-management/value-objects/task-status.vo.js'
import { RepositoryError } from '../../src/core/shared/types/errors.js'
import { aTask } from '../helpers/builders.js'
import { FixedClock } from '../helpers/fakes.js'

describe('SqliteTaskRepository (integration)', () => {
  let db: DatabaseSync
  let repo: SqliteTaskRepository

  beforeEach(() => {
    db = new DatabaseSync(':memory:')
    initTaskManagementSchema(db)
    repo = new SqliteTaskRepository(db)
  })

  afterEach(() => {
    db.close()
  })

  it('round-trips a task through save and findById', async () => {
    const task = aTask({ description: 'Round trip', priority: Priority.high() })
    await repo.save(task)

    const loaded = await repo.findById(task.id)

    expect(loaded).not.toBeNull()
    expect(loaded?.id.equals(task.id)).toBe(true)
    expect(loaded?.description).toBe('Round trip')
    expect(loaded?.priority.equals(Priority.high())).toBe(true)
    expect(loaded?.status.isPending()).toBe(true)
    expect(loaded?.assignedAgentId).toBeUndefined()
    expect(loaded?.createdAt).toEqual(task.createdAt)
    expect(loaded?.updatedAt).toEqual(task.updatedAt)
    expect(loaded?.version).toBe(0)
    expect(loaded?.domainEvents).toHaveLength(0)
  })

  it('returns null for unknown ids', async () => {
    expect(await repo.findById(TaskId.create())).toBeNull()
  })

  it('upserts on second save (INSERT OR REPLACE)', async () => {
    const task = aTask()
    await repo.save(task)

    const assigned = task.assignTo('agent-9')
    await repo.save(assigned)

    const loaded = await repo.findById(task.id)
    expect(loaded?.status.isAssigned()).toBe(true)
    expect(loaded?.assignedAgentId).toBe('agent-9')
    expect(loaded?.version).toBe(1)

    const all = await repo.findByStatus(TaskStatus.assigned())
    expect(all).toHaveLength(1)
  })

  it('orders pending tasks by priority rank, then FIFO', async () => {
    const early = new FixedClock(new Date('2026-01-01T00:00:00Z'))
    const late = new FixedClock(new Date('2026-01-02T00:00:00Z'))
    const lowEarly = aTask({ priority: Priority.low(), clock: early })
    const highLate = aTask({ priority: Priority.high(), clock: late })
    const criticalLate = aTask({ priority: Priority.critical(), clock: late })
    const highEarly = aTask({ priority: Priority.high(), clock: early })

    for (const t of [lowEarly, highLate, criticalLate, highEarly]) {
      await repo.save(t)
    }

    const pending = await repo.findPendingTasks()

    expect(pending.map((t) => t.id.value)).toEqual([
      criticalLate.id.value,
      highEarly.id.value,
      highLate.id.value,
      lowEarly.id.value
    ])
  })

  it('finds tasks by agent id and by status', async () => {
    const mine = aTask().assignTo('agent-a')
    const theirs = aTask().assignTo('agent-b')
    const idle = aTask()
    for (const t of [mine, theirs, idle]) {
      await repo.save(t)
    }

    const byAgent = await repo.findByAgentId('agent-a')
    expect(byAgent).toHaveLength(1)
    expect(byAgent[0]?.id.equals(mine.id)).toBe(true)

    const pending = await repo.findByStatus(TaskStatus.pending())
    expect(pending).toHaveLength(1)
    expect(pending[0]?.id.equals(idle.id)).toBe(true)
  })

  it('deletes tasks', async () => {
    const task = aTask()
    await repo.save(task)

    await repo.delete(task.id)

    expect(await repo.findById(task.id)).toBeNull()
  })

  it('surfaces corrupt rows as RepositoryError', async () => {
    const id = crypto.randomUUID()
    db.prepare(
      `INSERT INTO tasks (id, description, priority, priority_rank, status,
        assigned_agent_id, created_at, updated_at, version)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`
    ).run(
      id,
      'corrupt',
      'not-a-priority',
      99,
      'pending',
      null,
      '2026-01-01T00:00:00.000Z',
      '2026-01-01T00:00:00.000Z',
      0
    )

    await expect(repo.findById(TaskId.fromString(id))).rejects.toBeInstanceOf(
      RepositoryError
    )
  })
})

