// alongside the work-order UI.
const NAV = [
  { href: "/portal", label: "Dashboard", icon: LayoutDashboard },
  { href: "/portal/projects", label: "Projects", icon: FolderKanban },
  { href: "/portal/tickets", label: "Tickets", icon: Ticket },
