    update = { error: null }
  } = opts;
  return buildStubClient({
    user,
    tables: {
      company_members: { selectSingle: { data: member }, insert, update },
      company_roles: { selectSingle: { data: roleValid ? { key: "employee", rank } : null } }
    }
  }).supabase;
}

