  user_id: "other_user"
};

function makeClient(
  opts: {
    user?: { id: string; email: string } | null;
    member?: Record<string, unknown> | null;
    rank?: number;
    roleValid?: boolean;
    insert?: { data?: unknown; error?: { message: string } | null };
    update?: { error?: { message: string } | null };
  } = {}
) {
